1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
11	    background: #eceef1; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
12	  }
13	  .calc {
14	    width: min(320px, 100vw - 32px); padding: 16px; border-radius: 20px;
15	    background: #1f2227; box-shadow: 0 12px 32px rgba(0,0,0,.25);
16	  }
17	  .display {
18	    height: 80px; margin-bottom: 16px; padding: 0 12px; border-radius: 12px;
19	    background: #2b2f36; color: #fff; font-size: 40px; text-align: right;
20	    line-height: 80px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
21	  }
22	  .keys { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
23	  button {
24	    height: 60px; border: 0; border-radius: 12px; font-size: 22px; cursor: pointer;
25	    background: #3a3f47; color: #fff;
26	  }
27	  button:active { filter: brightness(1.25); }
28	  .op { background: #f59e0b; }
29	  .clear { background: #9ca3af; color: #111; }
30	  .wide { grid-column: span 2; }
31	</style>
32	</head>
33	<body>
34	<div class="calc">
35	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
36	  <div class="keys">
37	    <button class="clear" data-testid="key-clear">AC</button>
38	    <button class="clear" data-testid="key-sign">±</button>
39	    <button class="clear" data-testid="key-percent">%</button>
40	    <button class="op" data-testid="key-div" data-op="/">÷</button>
41	    <button class="clear wide" data-testid="key-lparen">(</button>
42	    <button class="clear wide" data-testid="key-rparen">)</button>
43	    <button data-testid="key-7" data-digit="7">7</button>
44	    <button data-testid="key-8" data-digit="8">8</button>
45	    <button data-testid="key-9" data-digit="9">9</button>
46	    <button class="op" data-testid="key-mul" data-op="*">×</button>
47	    <button data-testid="key-4" data-digit="4">4</button>
48	    <button data-testid="key-5" data-digit="5">5</button>
49	    <button data-testid="key-6" data-digit="6">6</button>
50	    <button class="op" data-testid="key-sub" data-op="-">−</button>
51	    <button data-testid="key-1" data-digit="1">1</button>
52	    <button data-testid="key-2" data-digit="2">2</button>
53	    <button data-testid="key-3" data-digit="3">3</button>
54	    <button class="op" data-testid="key-add" data-op="+">+</button>
55	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
56	    <button data-testid="key-dot">.</button>
57	    <button class="op" data-testid="key-equals">=</button>
58	  </div>
59	</div>
60	<script>
61	  var entry = "0";      // text of the current entry or last result
62	  var stored = null;    // left operand
63	  var op = null;        // pending operator
64	  var fresh = true;     // next digit starts a new entry
65	  var waiting = false;  // an operator was just pressed and has no right operand yet
66	  var error = false;    // set by a non-finite result; only clear leaves it
67	  var groups = [];      // outer {stored, op} saved by each open parenthesis
68	
69	  var display = document.querySelector('[data-testid="calc-display"]');
70	
71	  function compute(a, b, o) {
72	    if (o === "+") return a + b;
73	    if (o === "-") return a - b;
74	    if (o === "*") return a * b;
75	    return a / b;
76	  }
77	
78	  // Presentation only: at most 10 significant digits, no trailing zeros,
79	  // exponential below 1e-9 or from 1e10. Stored values are never rounded.
80	  function format(v) {
81	    if (v === 0) return "0";
82	    var r = Number(v.toPrecision(10));
83	    var a = Math.abs(r);
84	    if (a >= 1e10 || a < 1e-9) return r.toExponential();
85	    var e = Math.floor(Math.log10(a));
86	    if (Math.pow(10, e) > a) e--;
87	    var s = r.toFixed(Math.max(0, 9 - e));
88	    return s.indexOf(".") === -1 ? s : s.replace(/0+$/, "").replace(/\.$/, "");
89	  }
90	
91	  // While typing, the entry shows exactly as typed; results are formatted.
92	  function render() {
93	    display.textContent = error ? "Error" : fresh ? format(Number(entry)) : entry;
94	    display.setAttribute("data-value", String(Number(entry)));
95	    display.setAttribute("data-error", String(error));
96	  }
97	
98	  function digit(d) {
99	    if (fresh) { entry = d; fresh = false; }
100	    else entry = entry === "0" || entry === "-0" ? entry.slice(0, -1) + d : entry + d;
101	    waiting = false;
102	  }
103	
104	  function dot() {
105	    if (fresh) { entry = "0."; fresh = false; }
106	    else if (entry.indexOf(".") === -1) entry += ".";
107	    waiting = false;
108	  }
109	
110	  // Acts on the current entry. A typed entry keeps its text; a result is negated as a value.
111	  function sign() {
112	    if (!fresh) entry = entry.charAt(0) === "-" ? entry.slice(1) : "-" + entry;
113	    else entry = String(-Number(entry));
114	    waiting = false;
115	  }
116	
117	  // Acts on the current entry; the result is a value, so the next digit starts a new entry.
118	  function percent() {
119	    entry = String(Number(entry) / 100);
120	    fresh = true;
121	    waiting = false;
122	  }
123	
124	  // Immediate execution: each operator finishes the waiting operation, strictly
125	  // left to right, no precedence. 2 + 3 × 4 = is 20. The display always shows a real result.
126	  function operator(o) {
127	    if (op !== null && !waiting) finish(compute(stored, Number(entry), op));
128	    stored = Number(entry);
129	    op = o;
130	    fresh = true;
131	    waiting = true;
132	  }
133	
134	  // Division by zero (or any non-finite result) enters the error state.
135	  function finish(result) {
136	    entry = String(result);
137	    if (!isFinite(result)) error = true;
138	  }
139	
140	  // A group saves the outer operation and starts a fresh one inside.
141	  // Inside a group the same left-to-right rule applies.
142	  function lparen() {
143	    groups.push({ stored: stored, op: op });
144	    entry = "0"; stored = null; op = null; fresh = true; waiting = false;
145	  }
146	
147	  // Closing finishes the inner operation; its result becomes the outer right operand.
148	  function rparen() {
149	    if (groups.length === 0) return;
150	    if (op !== null && !waiting) finish(compute(stored, Number(entry), op));
151	    var g = groups.pop();
152	    stored = g.stored;
153	    op = g.op;
154	    fresh = true;
155	    waiting = false;
156	  }
157	
158	  // Equals closes any open groups first.
159	  function equals() {
160	    while (groups.length && !error) rparen();
161	    if (op === null || error) return;
162	    finish(compute(stored, Number(entry), op));
163	    stored = null;
164	    op = null;
165	    fresh = true;
166	    waiting = false;
167	  }
168	
169	  function clear() {
170	    entry = "0"; stored = null; op = null; fresh = true; waiting = false; error = false; groups = [];
171	  }
172	
173	  document.querySelector(".keys").addEventListener("click", function (e) {
174	    var b = e.target.closest("button");
175	    if (!b) return;
176	    var id = b.getAttribute("data-testid");
177	    if (error && id !== "key-clear") return;
178	    if (b.hasAttribute("data-digit")) digit(b.getAttribute("data-digit"));
179	    else if (b.hasAttribute("data-op")) operator(b.getAttribute("data-op"));
180	    else if (id === "key-dot") dot();
181	    else if (id === "key-sign") sign();
182	    else if (id === "key-percent") percent();
183	    else if (id === "key-lparen") lparen();
184	    else if (id === "key-rparen") rparen();
185	    else if (id === "key-equals") equals();
186	    else if (id === "key-clear") clear();
187	    render();
188	  });
189	
190	  render();
191	</script>
192	</body>
193	</html>
